// tianwen | DiPlay property client; vehicle implementation is in a separate GD bridge APK.
plugins { id("com.android.library") }

dependencies { implementation(libs.androidx.core.ktx) }

android {
    namespace = "com.shilapi.xcertplay.vehicleprobe"
    compileSdk {
        version = release(37)
    }
    // tianwen | Use the Java contract generated by GD; the matching .aidl remains the protocol source.
    buildFeatures { aidl = false }
    defaultConfig {
        // The client follows DiPlay; the separately installed GD bridge still needs Android 9.
        minSdk = 24
        consumerProguardFiles("consumer-rules.pro")
    }
    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_11
        targetCompatibility = JavaVersion.VERSION_11
    }
}
